// ?setCaptionText@Drawable@@QAEXABVUnicodeString@@@Z
// partial score=0.643 date=2026-09-28
// cl: /DNDEBUG /DWIN32 /D_WINDOWS /MD /EHsc /Igame/Libraries/Source/WWVegas/WWLib

// START HERE NEXT: this is the best known body.  388 B vs retail 381 B,
// 140 non-relocation bytes wrong (down from 392 B / 301 bytes on the
// 2026-09-27 attempt).  Only TWO structural families are left - the ZERO
// REGISTER (4 of the 9 structural diffs) and the /EHsc SCOPE SHAPE
// (5 of the 9) - plus the frame-slot rotation that costs the length.
// Both are written out with evidence at the bottom of this file.
// Verified by tools/probe.py and by compiling this file under its own
// // cl: line: put it at game/GameEngine/Source/GameClient/ to iterate.
//
// BFME Drawable::setCaptionText, 0x00418880, 381 bytes.  Reached from
// GameLogic::logicMessageDispatcher (0x0043xxxx, matched) through the ILT
// thunk ?j_00418880; the readable Zero Hour body is
// inputs/reference/CnC_Generals_Zero_Hour/GeneralsMD/Code/GameEngine/Source/
// GameClient/Drawable.cpp:4317 (setCaptionText) and :4354 (clearCaptionText,
// inlined into it) and every branch here comes from them.
//
// The body does NOT fit Drawable.cpp, and not because of the source: that TU
// compiles against the Zero Hour headers, so its DisplayString vtable carries
// the MEMORY_POOL_GLUE_WITH_USERLOOKUP_CREATE slot (retail calls setText at
// +0x04, the vendored header reaches +0x08), its DisplayStringManager reaches
// newDisplayString at +0x18 (retail +0x24), and its InGameUI caption accessors
// read +0x1928/+0x192C where retail reads +0x7C8/+0x7CC.  Those are vtable and
// field displacements baked into the compiled bytes, not source spelling.
// Drawable::drawConstructPercent (0x0041FDF0, matched) already proved the
// BFME layout for the same class and the same four call sites, so setCaptionText
// lives beside it and the vendored copy in Drawable.cpp gives way.

#include <stddef.h>

#include "string_base.h"

// Retail's caption text is a StringBase<unsigned short>, not the Zero Hour
// four-byte header: the emptiness test is the inline m_data/m_length pair
// retail inlines at +0x20, the copy constructor is
// ??0?$StringBase@G@@AAE@ABV0@@Z (0x00888400) and the temporary's destructor
// folds onto ?releaseBuffer@?$StringBase@G@@AAEXXZ (0x008881D0).  The copy
// constructor and destructor stay INLINE forwarders or every by-value argument
// site transposes.
class UnicodeString : private StringBase<unsigned short>
{
public:
	UnicodeString() : StringBase<unsigned short>() {}
	UnicodeString( const UnicodeString &other ) : StringBase<unsigned short>( other ) {}
	~UnicodeString() { releaseBuffer(); }
	bool isEmpty() const { return m_data == 0 || m_data->length == 0; }
	int compare( const UnicodeString &other ) const;
};

// The font name the caption is drawn with is a StringBase<char> temporary:
// retail destroys it through ?releaseBuffer@BFMERetailAsciiString@@AAEXXZ
// (0x00887940) at +0xFC, after the getFont call at +0xEC.
class AsciiString : private StringBase<char>
{
public:
	~AsciiString() { releaseBuffer(); }
};

typedef unsigned char UnsignedByte;
typedef int Int;
typedef float Real;

class GameFont;

// retail vtable: 0 dtor, 1 setText, 2 getText, 3 getTextLength, 4
// notifyTextChanged, 5 reset, 6 setFont
class DisplayString
{
public:
	virtual void slot00();
	virtual void setText( UnicodeString text );
	virtual UnicodeString getText();
	virtual void slot0c();
	virtual void slot10();
	virtual void slot14();
	virtual void setFont( GameFont *font );
};

// retail vtable: newDisplayString at +0x24, freeDisplayString at +0x28
class DisplayStringManager
{
public:
	virtual void slot00();
	virtual void slot04();
	virtual void slot08();
	virtual void slot0c();
	virtual void slot10();
	virtual void slot14();
	virtual void slot18();
	virtual void slot1c();
	virtual void slot20();
	virtual DisplayString *newDisplayString();
	virtual void freeDisplayString( DisplayString *string );
};

class LanguageFilter
{
public:
	void filterLine( UnicodeString &line );
};

class GlobalLanguageData
{
public:
	Int adjustFontSize( Int pointSize );
};

class FontLibrary
{
public:
	GameFont *getFont( AsciiString *name, Real pointSize, UnsignedByte bold );
};

// retail InGameUI: the caption font name at +0x7C4, its point size at +0x7C8
// and the bold flag at +0x7CC.  getDrawableCaptionFontName is not inlined --
// it is the body at 0x00415BF0, reached here through the ILT thunk.
class InGameUI
{
	UnsignedByte m_pad000[ 0x7c4 ];

public:
	AsciiString m_drawableCaptionFont;
	Int m_drawableCaptionPointSize;
	UnsignedByte m_drawableCaptionBold;

	AsciiString getDrawableCaptionFontName();
	Int getDrawableCaptionPointSize() { return m_drawableCaptionPointSize; }
	UnsignedByte isDrawableCaptionBold() { return m_drawableCaptionBold; }
};

// retail Drawable: the caption display string is the member at +0x2D0
class Drawable
{
	UnsignedByte m_pad000[ 0x2d0 ];

public:
	DisplayString *m_captionDisplayString;

	void setCaptionText( const UnicodeString &captionText );
};

typedef AsciiString (InGameUI::*CaptionFontNameCall)();
union CaptionFontNameValue
{
	void (*freeFunction)();
	CaptionFontNameCall memberFunction;
};

typedef GameFont *(FontLibrary::*GetFontCall)( AsciiString *, Real, UnsignedByte );
union GetFontValue
{
	void (*freeFunction)();
	GetFontCall memberFunction;
};

typedef Int (GlobalLanguageData::*AdjustFontSizeCall)( Int );
union AdjustFontSizeValue
{
	void (*freeFunction)();
	AdjustFontSizeCall memberFunction;
};

extern void j_0003b75f();
extern void j_0000abc3();
extern void j_00004e67();

#define DRAWABLE_CAPTION_GLOBAL(type, address) \
	(*reinterpret_cast<type **>( address ))

void Drawable::setCaptionText( const UnicodeString &captionText )
{
	if ( captionText.isEmpty() )
	{
		if ( m_captionDisplayString )
		{
			DRAWABLE_CAPTION_GLOBAL( DisplayStringManager, 0x012f12cc )
				->freeDisplayString( m_captionDisplayString );
		}
		m_captionDisplayString = 0;
		return;
	}

	{
		UnicodeString sanitizedString = captionText;
		DRAWABLE_CAPTION_GLOBAL( LanguageFilter, 0x012f1570 )->filterLine( sanitizedString );

		if ( m_captionDisplayString == 0 )
		{
			CaptionFontNameValue fontNameCall = { j_0003b75f };
			GetFontValue getFontCall = { j_0000abc3 };
			AdjustFontSizeValue adjustCall = { j_00004e67 };
			m_captionDisplayString = DRAWABLE_CAPTION_GLOBAL( DisplayStringManager, 0x012f12cc )
				->newDisplayString();
			GameFont *font =
				(DRAWABLE_CAPTION_GLOBAL( FontLibrary, 0x012f1b38 )->*getFontCall.memberFunction)(
					&(DRAWABLE_CAPTION_GLOBAL( InGameUI, 0x012f148c )->*fontNameCall.memberFunction)(),
					(Real)(DRAWABLE_CAPTION_GLOBAL( GlobalLanguageData, 0x012f1484 )
						->*adjustCall.memberFunction)(
							DRAWABLE_CAPTION_GLOBAL( InGameUI, 0x012f148c )
								->getDrawableCaptionPointSize() ),
					DRAWABLE_CAPTION_GLOBAL( InGameUI, 0x012f148c )->isDrawableCaptionBold() );
			m_captionDisplayString->setFont( font );
			m_captionDisplayString->setText( sanitizedString );
		}
		else
		{
			// set the string if the value has changed
			if ( m_captionDisplayString->getText().compare( sanitizedString ) != 0 )
			{
				m_captionDisplayString->setText( sanitizedString );
			}
		}
	}
}

#undef DRAWABLE_CAPTION_GLOBAL

// ------------------------------------------------------------------
// MEASURED 2026-09-28 (probe.py / cmp.py, MSVC 7.1 /EHsc -O2):
//   ours 388 B vs retail 381 B, 15 relocations all resolving,
//   shape 0.938, 9 structural differences, 140 non-relocation bytes
//   wrong (the banked 0.8 attempt measured 392 B / 301 bytes).
//
// WHAT CHANGED SINCE THE LAST BANKED ATTEMPT (both source-level, both
// confirmed against the Zero Hour twin, and both worth keeping):
//   * `m_captionDisplayString = 0;` moved OUT of the
//     `if (m_captionDisplayString)` guard.  The Zero Hour body calls
//     clearCaptionText(), whose body is
//         if (m_captionDisplayString) ...freeDisplayString(...);
//         m_captionDisplayString = NULL;
//     i.e. the null store is the SHARED tail.  With it inside the guard
//     MSVC has to end the branch at `mov [esi+0x2D0],ebx` and jump the
//     `je` all the way to the epilogue (6-byte `0f 84`); with it outside,
//     the `je` at +0x37 is the retail 2-byte `74 0C` onto +0x45 and the
//     early-return path loses 4 bytes.  That single line is most of the
//     301 -> 140 byte improvement.
//   * `sanitizedString` and the whole caption body wrapped in a block, per
//     docs/shape_levers.md "A dead parameter slot takes only block-scoped
//     locals".  Byte-identical to the unblocked form (388 B / 140 bytes
//     either way) - it did NOT move the local into the dead parameter
//     slot.  Kept because it is the shape the retail frame implies; the
//     slot is still open (see the frame table below).
//
// STILL EXACT (do not re-derive):
//   * the /EHsc prologue ORDER (mov eax,fs:[0] / push -1 / push scope /
//     push eax / mov fs:[0],esp) and `sub esp,8` + push ebx + push esi;
//   * the SHORT `je +0x0C` onto the shared null store;
//   * freeDisplayString @ [edx+0x28], newDisplayString @ [edx+0x24]
//     (the vendored Drawable.cpp header reaches +0x1C / +0x18);
//   * setText @ [eax+4], getText @ [edx+8], setFont @ [eax+0x18];
//   * InGameUI caption accessors at +0x7C8 / +0x7CC (vendored ZH: +0x1928
//     / +0x192C) and getFont's Real fild/fstp int->float pair (vendored
//     getFont takes Int and emits no conversion at all);
//   * the AsciiString temporary lives to the end of the getFont STATEMENT
//     (dtor right after getFont, before setFont);
//   * the display-string vptr load sits after getFont, not hoisted across
//     it, which only happens when getFont is its own `GameFont *font =`
//     statement.
//   * this-relative: m_captionDisplayString at Drawable+0x2D0.
//
// THE NINE REMAINING STRUCTURAL DIFFERENCES split cleanly into two
// families.  Only these two are left; nothing else differs structurally.
//
// A. THE ZERO REGISTER (4 of the 9; the standing blocker row 5737 calls
//    it "MSVC's ZERO-REGISTER HOIST"; eight verdicts have failed on it).
//    retail +0x22 `push edi; xor edi,edi` -> `cmp eax,edi` ->
//    `cmp word [eax+4],di` -> `cmp eax,edi` -> `mov [esi+0x2D0],edi`,
//    with edi later REUSED for the AsciiString temp (+0xAC) and the font
//    (+0xF5); bl carries the compare bool (`setne bl` / `test bl,bl`).
//    ours hoists the same 0 into ebx, so `push edi` lands 4 bytes late and
//    the bool loses its register:
//      `xor ebx,ebx` / `cmp eax,ebx` / `push edi` / `cmp word [eax+4],bx`
//      / `setne byte [esp+0x24]` / `cmp byte [esp+0x24],bl`
//    Both bodies push the SAME three callee-saved registers in the SAME
//    order (ebx, esi, edi) and assign them differently: retail gives the
//    constant edi and the bool ebx, ours gives the constant ebx and
//    SPILLS the bool.  So this is not a register shortage - both have
//    three slots for {this, constant, temp} plus a short-lived bool - it
//    is which slot the allocator commits first.  Nothing in the source
//    moved it in eight sessions (see DISPROVED).
//
// B. THE /EHsc SCOPE SHAPE (5 of the 9).  Retail's four state stores are
//    0 at +0x74, 1 at +0xCF, 0 at +0xF7, -1 at +0x15C, and it opens TWO
//    setText scopes, one per branch:
//      new path  +0x10D `push ecx` / +0x10E `mov [esp+0x14],esp`
//      else path +0x13C `push ecx` / +0x13D `mov [esp+0x10],esp`
//    with `jmp +0x141` at +0x112 so the copyctor/setText/cleanup code is
//    still shared.  Ours opens ONE scope inside the shared block and
//    spends two extra state stores on a scope retail does not have:
//      +0x11F `mov byte [esp+0x20],2` (enter) / +0x134 `mov byte
//      [esp+0x1c],bl` (leave) around the getText() return temporary, and
//      the __$EHRec$ store at +0x14A instead of before the merge at
//      +0x13D.  The extra scope-2 pair is a tail-merge decision: ours
//      merges the `push ecx; mov [esp+N],esp` argument-slot setup INTO
//      the shared block, retail keeps it per branch and merges only from
//      the copyctor on.
//
// C. THE FRAME ROTATION (not counted above; it is pure displacement and
//    costs the remaining length).  Measured with /FAsc /Fa on this body
//    and read off retail by tracking esp through the CFG (callee `ret N`
//    known per symbol: StringBase ctor 4, filterLine 4, getFont 12,
//    adjustFontSize 4, releaseBuffer 0, compare 4, setFont/setText/
//    free/new/getText 4).  Offsets below are relative to the esp after
//    the prologue; negative is below it.
//      RETAIL   +4  sanitizedString  (the DEAD INCOMING PARAMETER slot)
//               -4  the /EHsc state byte (it overwrites the pushed -1)
//              -16  the shared $T: AsciiString temp, getText() return
//                   temp, and BOTH __$EHRec$ scope records
//              -20  the UnsignedByte bold temporary
//              -24  the Int adjustFontSize result that `fild` reads
//      OURS    -16  sanitizedString, SHARING the $T slot with the AsciiString
//                   temp and the getText() return temp
//               -4  the state byte (agrees)
//               +4  tv336 (the Int temp), $T986 (bold), $T964 (the compare
//                   bool) and $T966 (the scope record) all crowded into
//                   the dead parameter slot that retail gave the local
//    The /Fa table for ours reads `_sanitizedString$ = -20, $T962 = -16,
//    $T965 = -16, __$EHRec$ = -12, tv336 = 8, $T986 = 8, $T964 = 8,
//    $T966 = 8, _captionText$ = 8`.  So the fix is ONE more frame object,
//    not a respelling: retail has five distinct slots where ours has two
//    crowded ones, and the user local is the one that must move UP into
//    the dead parameter slot while the four compiler temporaries move
//    DOWN to -16/-20/-24.  docs/shape_levers.md "A run of locals on the
//    wrong slots: retail had one more object" - count the objects, do not
//    reorder the declarations.
//
// DISPROVED ON THIS BODY (each cost a compile; do not retry blind):
//   * `throw()` on UnicodeString::compare, on DisplayString::setText /
//     getText / setFont, /EHsc- instead of /EHsc, and the
//     `_STLP_NO_EXCEPTIONS` / nothrow `operator delete[]` pairs - all six
//     eh_levers choices, 128 combinations, run through shape_search with
//     a 12-trial budget: "6 trials; no improving output".  throw() on
//     compare removes the two extra state stores but then drops `push ebx`
//     entirely, so the zero falls back to `test eax,eax` and immediates
//     (shape 0.938 -> 0.876, structural count 9 -> 15).
//   * `throw()` aside, tools/shape_family_levers.py reports "no applicable
//     source-level family lever" for all ten families on this body.
//   * naming the compare result (`bool changed = ... != 0; if (changed)`)
//     is byte-identical to the inline form.
//   * `else if (...)` with no braces instead of `else { if (...) {...} }`
//     is byte-identical (388 B / 140 bytes).
//   * `GameFont *font; font = ...;` as two statements instead of one
//     initialiser is byte-identical (388 B / 140 bytes).
//   * naming the font arguments as block-scoped locals
//     (`UnsignedByte bold = ...; Int pointSize = ...;
//      Int adjustedSize = adjustFontSize(pointSize);`) is much WORSE:
//     414 B / 226 bytes / 16 relocs.
//   * naming the getText() result
//     (`UnicodeString currentText = m_captionDisplayString->getText();`)
//     is much WORSE: 409 B / 135 bytes / 16 relocs.
//   * declaring the local at function scope and assigning it after the
//     empty check (`UnicodeString sanitizedString; ... sanitizedString =
//     captionText;`) is much WORSE: 397 B / 275 bytes / 16 relocs.
//   * writing the empty-caption path as a call to an in-class inline
//     `clearCaptionText()` - i.e. the literal Zero Hour shape - is
//     byte-identical to the inlined form (388 B / 140 bytes).  The name
//     is real (GeneralsMD Drawable.cpp:4354) but the spelling buys
//     nothing here; keep whichever form is shorter.
